// What the editor of commands in code explains: every function of Petto Code and the data the code can read, in the
// three languages of the dashboard. Ported from the Petto Code Generator. The names and the numbers of arguments that
// the editor trusts come from the bot (meta.functions); this only adds the words.
export type CatalogLang = 'en' | 'es' | 'pt';
export type Texts = Record<CatalogLang, string>;
export interface CatalogFunction { group: string; name: string; insert: string; text: Texts }
const F = (group: string, name: string, insert: string, en: string, es: string, pt: string): CatalogFunction => ({ group, name, insert, text: { en, es, pt } });

