/** What the parts of the data are, for the first step of a path such as `.User`. */
export const DATA_GROUPS: Record<string, Texts> = {
  User: { en: 'Who used it', es: 'Quien lo usó', pt: 'Quem usou' },
  Member: { en: 'Who used it, as a member of the server', es: 'Quien lo usó, como miembro del servidor', pt: 'Quem usou, como membro do servidor' },
  Guild: { en: 'The server', es: 'El servidor', pt: 'O servidor' },
  Channel: { en: 'The channel', es: 'El canal', pt: 'O canal' },
  Message: { en: 'The message', es: 'El mensaje', pt: 'A mensagem' },
  Button: { en: 'The button or menu used', es: 'El botón o menú usado', pt: 'O botão ou menu usado' },
  Reaction: { en: 'The reaction', es: 'La reacción', pt: 'A reação' },
  Modal: { en: 'The form sent', es: 'El formulario enviado', pt: 'O formulário enviado' },
};

/** The words of the language itself, offered with the functions. */
export const KEYWORDS = ['if', 'else', 'end', 'range', 'with', 'define', 'template', 'break', 'continue', 'return', 'true', 'false', 'nil'];

export interface DataEntry { name: string; path: string; text: Texts | null; children: boolean }

/** The fields that can follow a path: '' gives User, Member, Args...; 'User' gives ID, Username... */
export function dataChildren(parent: string): DataEntry[] {
  const seen = new Map<string, DataEntry>();
  const depth = parent ? parent.split('.').length : 0;
  for (const [full, text] of DATA) {
    const parts = full.slice(1).split('.');
    if (parts.length <= depth || parts.slice(0, depth).join('.') !== parent) continue;
    const name = parts[depth];
    const path = parts.slice(0, depth + 1).join('.');
    const children = parts.length > depth + 1;
    const entry = seen.get(name);
    if (entry) { entry.children ||= children; if (!children) entry.text = text; continue; }
    seen.set(name, { name, path, text: children ? DATA_GROUPS[path] ?? null : text, children });
  }
  return [...seen.values()];
}

export const catalogLang = (dashLang: string): CatalogLang => (dashLang === 'es' ? 'es' : dashLang.startsWith('pt') ? 'pt' : 'en');
